function PTTT_Label(e)
	local s = PTNV_CH[e.c].title .. ": "
	local nd = PTNV_Need(e.r)
	if nd.tot > 0 then s = s .. PTTT_T_MISS .. nd.tot .. PTTT_T_ITEMS
	elseif e.r.kill == 1 then s = s .. PTTT_T_FIGHT
	elseif nd.n > 0 then s = s .. PTTT_T_OK
	else s = s .. PTTT_T_NOITEM end
	return s
end

function PTTT_Page(p)
	PTNV_Load()
	local a = PTNV_Active()
	if a.n == 0 then
		Say(PTTT_T_NONE, 1, PTNV_T_CLOSE .. "/PTTT_No")
		return
	end
	local first, last, more = PTNV_Span(a.n, p)
	local o = {}
	local n = 0
	local i = first
	while i <= last do
		n = n + 1
		o[n] = PTNV_Clip(PTTT_Label(a[i]), 58) .. "/PTTT_A" .. i
		i = i + 1
	end
	if more then n = n + 1 o[n] = PTNV_T_NEXT .. "/PTTT_P" .. (p + 1) end
	if p > 1 then n = n + 1 o[n] = PTNV_T_BACK .. "/PTTT_P" .. (p - 1) end
	n = n + 1 o[n] = PTNV_T_CLOSE .. "/PTTT_No"
	PTNV_Say(PTTT_T_TITLE, o)
end

function PTTT_Detail(i)
	PTNV_Load()
	local a = PTNV_Active()
	local e = a[i]
	if not e then PTTT_Page(1) return end
	local nd = PTNV_Need(e.r)
	local s = PTNV_StepText(e)
	if e.r.kill == 1 then
		if e.r.farm and e.r.farm > 0 then s = s .. "<enter>" .. PTTT_T_FARMNOTE .. PTNV_DS[e.r.farm].nm .. "."
		else s = s .. "<enter>" .. PTTT_T_KILLNOTE end
	elseif e.r.farm and e.r.farm > 0 and nd.tot > 0 then
		s = s .. "<enter>" .. PTTT_T_DROPNOTE .. PTNV_DS[e.r.farm].nm .. "."
	end
	local k = 1
	while k <= nd.n do
		local x = nd[k]
		s = s .. "<enter>- " .. x.it.nm .. PTTT_T_HAVE .. x.have .. PTTT_T_NEED .. x.it.n
		if x.miss > 0 then s = s .. PTTT_T_LACK .. x.miss end
		k = k + 1
	end
	if nd.n == 0 then s = s .. "<enter>" .. PTTT_T_NOTHING
	elseif nd.tot == 0 then s = s .. "<enter>" .. PTTT_T_ALLOK end
	local o = {}
	local n = 0
	if nd.tot > 0 then n = n + 1 o[n] = PTTT_T_CONFIRM .. "/PTTT_OK" .. i end
	n = n + 1 o[n] = PTNV_T_BACK .. "/PTTT_P" .. (floor((i - 1) / 4) + 1)
	n = n + 1 o[n] = PTNV_T_CLOSE .. "/PTTT_No"
	PTNV_Say(PTNV_Clip(s, 500), o)
end

function PTTT_Give(i)
	PTNV_Load()
	local a = PTNV_Active()
	local e = a[i]
	if not e then return end
	local nd = PTNV_Need(e.r)
	if nd.tot == 0 then Msg2Player(PTTT_T_ALLOK) return end
	local free = CalcFreeItemCellCount()
	if free < nd.kinds then
		Say(PTTT_T_ROOM1 .. nd.kinds .. PTTT_T_ROOM2 .. free .. PTTT_T_ROOM3, 1, PTNV_T_CLOSE .. "/PTTT_No")
		return
	end
	local k = 1
	local stop = nil
	while k <= nd.n and not stop do
		local x = nd[k]
		local got = 0
		while got < x.miss and not stop do
			if PTNV_GiveOne(x.it) > 0 then got = got + 1 else stop = 1 end
		end
		if got > 0 then Msg2Player(PTTT_T_GOT .. x.it.nm .. " x" .. got) end
		if stop then
			if CalcFreeItemCellCount() < 1 then Msg2Player(PTTT_T_FULL .. x.it.nm .. " x" .. (x.miss - got))
			else Msg2Player(PTTT_T_FAIL .. x.it.nm) end
		end
		k = k + 1
	end
	if not stop then Msg2Player(PTTT_T_DONE) end
	if e.r.kill == 1 then Msg2Player(PTTT_T_KILLNOTE) end
end

